SELECT percentile_cont(0.75) within GROUP (ORDER BY value) AS median_arterial_blood_gas_ph FROM labevents JOIN d_labitems ON labevents.itemid = d_labitems.itemid WHERE labevents.subject_id = 123456 AND d_labitems.label = 'Arterial blood gas pH' AND EXTRACT(YEAR FROM labevents.charttime) = 2019 AND EXTRACT(MONTH FROM labevents.charttime) = 10 AND EXTRACT(DAY FROM labevents.charttime) = 15 AND labevents.hadm_id IN (SELECT hadm_id FROM icustays WHERE first_careunit = 'ICU');